  "Type it at “Sign in with password” instead of your profile name. We never send anything to it; a forgotten password is still reset by your admin.": "Kirjoita se kohdassa ”Kirjaudu salasanalla” profiilinimesi sijaan. Emme koskaan lähetä siihen mitään; unohtuneen salasanan nollaa edelleen ylläpitäjäsi.",
