  "Added {0}": "Lisätty {0}",
  "Code from your other device": "Koodi toisesta laitteestasi",
  "Confirm with a passkey": "Vahvista pääsyavaimella",
  "Confirmed. Now create the new passkey; your browser will ask where to keep it.": "Vahvistettu. Luo nyt uusi pääsyavain; selaimesi kysyy, mihin se tallennetaan.",
  "Copy link": "Kopioi linkki",
  "Create a passkey on this device for the profile “{0}”. It signs you in here from now on.": "Luo tälle laitteelle pääsyavain profiilille ”{0}”. Se kirjaa sinut sisään tästä lähtien.",
  "Each one signs in to this profile from the device or password manager that keeps it. Tap one to rename or remove it.": "Jokainen niistä kirjaa tähän profiiliin siltä laitteelta tai salasananhallinnasta, johon se on tallennettu. Nimeä tai poista pääsyavain napauttamalla sitä.",
  "Enter the code from your other device.": "Anna koodi toisesta laitteestasi.",
  "For this device, a security key, a password manager, or your phone through the browser’s own QR code. First confirm that it is you.": "Tälle laitteelle, suojausavaimelle, salasananhallinnalle tai puhelimellesi selaimen oman QR-koodin kautta. Vahvista ensin, että se olet sinä.",
  "It can no longer sign in to this profile. A device already signed in with it stays signed in. If it was lost, use Sign out everywhere.": "Sillä ei voi enää kirjautua tähän profiiliin. Sillä jo kirjautunut laite pysyy kirjautuneena. Jos se katosi, käytä ”Kirjaudu ulos kaikkialta”.",
  "It is your only way in, so it cannot be removed until there is another.": "Se on ainoa tapasi päästä sisään, joten sitä ei voi poistaa ennen kuin lisäät toisen.",
  "Last used {0}": "Käytetty viimeksi {0}",
  "Make a new code": "Luo uusi koodi",
  "Name, e.g. Work laptop": "Nimi, esim. Työkannettava",
  "None yet. Add one and sign in without your password.": "Ei vielä yhtään. Lisää pääsyavain ja kirjaudu ilman salasanaa.",
