  "Remove this passkey?": "Poistetaanko tämä pääsyavain?",
  "Scan this with the other device, or open openGym there and enter the code on the sign-in screen. It works once, for {0} minutes.": "Skannaa tämä toisella laitteella tai avaa openGym siinä ja syötä koodi kirjautumisnäkymässä. Koodi toimii kerran, {0} minuutin ajan.",
  "That code is wrong, already used or expired. Make a new one on your other device.": "Koodi on väärä, jo käytetty tai vanhentunut. Luo uusi toisella laitteellasi.",
  "This browser cannot confirm with your passkey. Do this on a device that holds one.": "Tämä selain ei pysty vahvistamaan pääsyavaimella. Tee tämä laitteella, jolla pääsyavain on.",
  "First confirm that it is you.": "Vahvista ensin, että se olet sinä.",
  "This profile has no passkey, and this server does not take passwords, so nothing here can confirm that it is you. Ask your admin.": "Tällä profiililla ei ole pääsyavainta, eikä tämä palvelin hyväksy salasanoja, joten mikään ei voi vahvistaa henkilöllisyyttäsi. Kysy ylläpitäjältä.",
  "This browser cannot create passkeys, so it cannot be added with a code. Open the link in a browser that can.": "Tämä selain ei voi luoda pääsyavaimia, joten sitä ei voi lisätä koodilla. Avaa linkki selaimessa, joka tukee niitä.",
  "This browser is signed in as “{0}”. Adding it to “{1}” signs “{0}” out here.": "Tämä selain on kirjautunut profiiliin ”{0}”. Lisääminen profiiliin ”{1}” kirjaa profiilin ”{0}” ulos täältä.",
  "This code is for a different profile that is also called “{0}”, not the one this browser is signed in as. Adding it there signs yours out here.": "Tämä koodi kuuluu toiselle profiilille, jonka nimi on myös ”{0}”, ei sille, johon tämä selain on kirjautunut. Jos lisäät selaimen siihen, nykyinen profiilisi kirjataan ulos täältä.",
  "Only continue if this code comes from a device of your own. This browser is then signed in to “{0}”, and what you log here goes to that profile.": "Jatka vain, jos koodi on peräisin omalta laitteeltasi. Tämä selain kirjataan sen jälkeen profiiliin ”{0}”, ja kaikki tänne kirjaamasi tallentuu siihen profiiliin.",
  "This code has expired.": "Koodi on vanhentunut.",
  "This device already has a passkey for this profile.": "Tällä laitteella on jo pääsyavain tälle profiilille.",
