  "This profile already has as many passkeys as it can hold.": "Tällä profiililla on jo enimmäismäärä pääsyavaimia.",
  "Use a code from your other device": "Käytä koodia toiselta laitteeltasi",
  "You get a code that lets your phone or another computer create a passkey for this profile. First confirm that it is you.": "Saat koodin, jolla puhelimesi tai toinen tietokone voi luoda pääsyavaimen tälle profiilille. Vahvista ensin, että se olet sinä.",
