  "The end of a rest rings through silent. Music turns down for it and keeps playing.": "Tauon päättymisääni kuuluu myös äänettömässä tilassa. Musiikki hiljenee hetkeksi ja jatkaa soimista.",
  "The quieter three-beep sound from before 1.3.9, instead of the louder chime.": "Ennen versiota 1.3.9 käytetty hiljaisempi kolmen piippauksen ääni voimakkaamman merkkiäänen sijaan.",
