  "Saves a dated copy to Documents/openGym after finishing a workout or editing a routine, and keeps the newest {0}. Point a sync app at that folder, or copy it out by hand.": "Tallentaa päivätyn kopion kansioon Documents/openGym treenin päättämisen tai ohjelman muokkauksen jälkeen ja säilyttää {0} uusinta. Ohjaa synkronointisovellus siihen kansioon tai kopioi tiedostot käsin.",
  "Reset everything?": "Nollataanko kaikki?",
  "Reset everything": "Nollaa kaikki",
  "Deletes your plan, workouts, body weight, photos and videos on this device. This cannot be undone.": "Poistaa suunnitelmasi, treenisi, kehonpainosi, kuvasi ja videosi tältä laitteelta. Tätä ei voi perua.",
  "Deletes your plan, workouts, body weight, photos and videos from your profile on this server and on every signed-in device. This cannot be undone.": "Poistaa suunnitelmasi, treenisi, kehonpainosi, kuvasi ja videosi profiilistasi tällä palvelimella ja kaikilta kirjautuneilta laitteilta. Tätä ei voi perua.",
  "Sync failed: the server refused the upload as too large. Your changes have not reached the server.": "Synkronointi epäonnistui: palvelin hylkäsi lähetyksen liian suurena. Muutoksesi eivät ole siirtyneet palvelimelle.",
  "This device is out of storage: the change is not saved on it. Signed in, it still goes to the server.": "Tämän laitteen tallennustila on täynnä: muutosta ei tallenneta laitteelle. Kirjautuneena se menee silti palvelimelle.",
