  "Deload routine": "Kevennysohjelma",
  "Its workouts do not count toward progression. They still show in history and statistics.": "Sen treenejä ei lasketa mukaan progressioon. Ne näkyvät silti historiassa ja tilastoissa.",
  "A deload routine opens at the numbers set here, so the progression above does not apply to it.": "Kevennysohjelma alkaa tässä määritellyistä luvuista, joten yllä oleva progressio ei koske sitä.",
  "Linear progression": "Lineaarinen progressio",
