  "Add time": "Lisää aikaa",
  "Targets stay where you set them.": "Tavoitteet pysyvät siinä, mihin ne asetit.",
  "Hit every rep in every set and the weight goes up. Repeated misses trigger a deload.": "Tee jokaisen sarjan kaikki toistot, niin paino nousee. Jos sarjat jäävät toistuvasti vajaiksi, seuraa kevennys.",
  "Two straight sets plus a final set taken to failure. Beat the target on that set and the weight goes up (twice as much if you double the reps). One failure resets 10 %.": "Kaksi suoraa sarjaa ja viimeinen sarja uupumukseen asti. Ylitä tavoite viimeisessä sarjassa, niin paino nousee (tuplasti, jos tuplaat toistot). Yksi vajaa sarja pudottaa painoa 10 %.",
  "Work up through a rep range at the same weight. Reach the top of the range in every set and the weight goes up, reps back to the bottom.": "Etene toistoalueen läpi samalla painolla. Kun saavutat ylärajan joka sarjassa, paino nousee ja toistot palaavat alarajalle.",
  "Hold every set for the full duration and the target goes up.": "Pidä jokainen sarja täyden ajan, niin tavoite nousee.",
  "Nothing logged yet, so this session sets the baseline.": "Mitään ei ole vielä kirjattu, joten tämä treenikerta asettaa lähtötason.",
  "Held every set for the full time. Target goes up by {0}s.": "Pidit jokaisen sarjan täyden ajan. Tavoite nousee {0} s.",
  "Short {0} sessions in a row. Back off to {1}s and build up again.": "Aika jäi vajaaksi {0} treenikertaa peräkkäin. Palaa aikaan {1} s ja rakenna siitä uudelleen.",
  "Came up short last time. Same target again.": "Viimeksi jäi hieman vajaaksi. Sama tavoite uudelleen.",
  "Top of the rep range in every set. {0} {1} more, back to {2} reps.": "Toistoalueen yläraja täynnä joka sarjassa. {0} {1} lisää, takaisin {2} toistoon.",
  "Stuck for {0} sessions. Deload to {1} {2}.": "Jumiutunut {0} treenikerran ajaksi. Kevennys painoon {1} {2}.",
  "Same weight, aim for {0} reps this time.": "Sama paino, tavoitteena tällä kertaa {0} toistoa.",
  "Last set hit {0} reps, twice the target! Take a double jump of {1} {2}.": "Viimeisessä sarjassa {0} toistoa, tuplasti tavoite! Nosta suoraan {1} {2}.",
  "Every rep last time. {0} {1} more.": "Kaikki toistot täyteen viimeksi. {0} {1} lisää.",
  "Every rep last time. {0} {1} less help.": "Kaikki toistot täyteen viimeksi. {0} {1} vähemmän avustusta.",
  "Top of the rep range in every set. {0} {1} less help, back to {2} reps.": "Toistoalueen yläraja täynnä joka sarjassa. {0} {1} vähemmän avustusta, takaisin {2} toistoon.",
  "Missed reps. {0} {1} of help while you build back up.": "Toistoja jäi vajaaksi. {0} {1} avustusta, kun rakennat voimaa takaisin.",
  "Stuck for {0} sessions. Back to {1} {2} of help, then build up again.": "Jumiutunut {0} treenikerran ajaksi. Palaa tasolle {1} {2} avustusta ja rakenna siitä uudelleen.",
  "Missed reps {0} sessions running. Reset to {1} {2} and work back up.": "Toistoja jäi vajaaksi {0} treenikertaa peräkkäin. Palaa painoon {1} {2} ja etene siitä uudelleen.",
  "Missed reps. Reset to {0} {1} and work back up.": "Toistoja jäi vajaaksi. Palaa painoon {0} {1} ja etene siitä uudelleen.",
  "Missed reps last time. Same weight again ({0} of {1} to go).": "Viimeksi jäi toistoja vajaaksi. Sama paino uudelleen ({0}/{1} jäljellä).",
  "Bodyweight: every rep last time, so go for {0} this time.": "Kehonpaino: kaikki toistot viimeksi, joten tähtää tällä kertaa tavoitteeseen {0}.",
  "Bodyweight: same target again until every set is clean.": "Kehonpaino: sama tavoite uudelleen, kunnes joka sarja on puhdas.",
  "{0} sets bring an {1} with them. Switch on Effort per set in Settings to see it.": "{0} sarjassa on mukana {1}-arvo. Ota asetuksista käyttöön Rasitus per sarja nähdäksesi sen.",
  "{0} sets bring an {1} with them.": "{0} sarjassa on mukana {1}-arvo.",
