  "RPE": "RPE",
  "Effort per set": "Sarjan rasitus",
  "What are RIR and RPE?": "Mitä ovat RIR ja RPE?",
  "How hard a set was, logged next to weight and reps. Two scales for the same judgement, counted from opposite ends.": "Kuinka raskas sarja oli, kirjattuna painon ja toistojen rinnalle. Kaksi asteikkoa samalle arviolle, laskettuna vastakkaisista päistä.",
  "How it felt": "Miltä tuntui",
  "Nothing left, went to failure": "Ei mitään jäljellä, uupumukseen asti",
  "One more rep in the tank": "Yksi toisto varastossa",
  "Two more reps": "Kaksi toistoa jäljellä",
  "Three more reps": "Kolme toistoa jäljellä",
  "Easy, warm-up territory": "Kevyt, lämmittelytasoa",
  "Maybe half a rep left": "Ehkä puolikas toisto jäljellä",
  "How hard was that set?": "Kuinka raskas sarja oli?",
  "Tap how many reps you had left, or type an exact {0}.": "Napauta, montako toistoa jäi jäljelle, tai syötä tarkka {0}.",
  "Exact {0}": "Tarkka {0}",
  "Clear rating": "Tyhjennä arvio",
  "RIR counts the reps you left in the tank; RPE reads the same effort off a 10-point scale, so RPE ≈ 10 − RIR. Pick whichever you already think in.": "RIR laskee varastoon jääneet toistot; RPE kuvaa saman rasituksen 10-portaisella asteikolla, eli RPE ≈ 10 − RIR. Valitse se, kumpi on sinulle tutumpi.",
  "The highlighted row is where most working sets land. Sets you have already logged keep their own scale, and nothing else reads the value, so progression and estimated 1RM are unaffected.": "Korostetulle riville osuu suurin osa työsarjoista. Jo kirjaamasi sarjat säilyttävät oman asteikkonsa, eikä mikään muu lue tätä arvoa, joten progressio ja arvioitu 1RM pysyvät ennallaan.",
  "Effort": "Rasitus",
  "how close to failure": "kuinka lähellä uupumusta",
  "by hard sets": "kovien sarjojen mukaan",
  "Hard": "Kova",
  "no hard sets": "ei kovia sarjoja",
  "No hard sets in this period": "Ei kovia sarjoja tällä jaksolla",
  "Every muscle group got at least one hard set in this period.": "Jokainen lihasryhmä sai vähintään yhden kovan sarjan tällä jaksolla.",
  "No rated sets in this period.": "Ei arvioituja sarjoja tällä jaksolla.",
  "average effort": "keskimääräinen rasitus",
  "at {0} {1} or harder": "tasolla {0} {1} tai kovempi",
  "{0} of {1} finished sets rated": "{0} / {1} tehdystä sarjasta arvioitu",
  "Week by week": "Viikko viikolta",
  "Where the sets land": "Mihin sarjat osuvat",
  "Most working sets belong close to failure, not at it. Half at the floor and half at the top still average out to a healthy-looking middle.": "Useimmat työsarjat kuuluvat lähelle uupumusta, eivät aivan loppuun asti. Puolet pohjalla ja puolet huipulla tuottaa silti keskiarvoksi hyvältä näyttävän keskivälin.",
  "Average effort per workout": "Keskimääräinen rasitus treeniä kohti",
  "A fuller dot means less left in the tank. The same weight at a lower {0} is progress the line alone doesn’t show.": "Täydempi piste tarkoittaa vähemmän varastossa. Sama paino, kun {0} on pienempi, on edistystä, jota viiva yksin ei näytä.",
  "Bodyweight": "Kehonpaino",
  "No weight to enter. Just log the reps.": "Ei syötettävää painoa. Kirjaa vain toistot.",
  "Ask for a weight on every set.": "Kysy painoa jokaisessa sarjassa.",
  "For dips or pull-ups with a belt. Progression then follows the weight.": "Dippeihin tai leuanvetoihin lisäpainovyöllä. Progressio seuraa silloin painoa.",
  "For lunges, single-arm rows and the like.": "Askelkyykkyihin, yhden käden soutuihin ja vastaaviin.",
  "Top of the range": "Yläraja",
  "Reps climb by one whenever every set was clean. Set a ceiling to add sets instead of reps forever.": "Toistot nousevat yhdellä aina, kun kaikki sarjat olivat puhtaita. Aseta yläraja, jotta sarjoja lisätään toistojen loputtoman kasvattamisen sijaan.",
  "Reps climb to {0}, then a set is added and the reps start over. At {1} sets it asks you to add weight instead.": "Toistot nousevat lukuun {0}, minkä jälkeen lisätään sarja ja toistot alkavat alusta. Kun sarjoja on {1}, sovellus pyytää lisäämään painoa.",
  "Added ({0})": "Lisäpaino ({0})",
  "{0}/side": "{0}/puoli",
  "{0} reps in every set! Add a set and go back to {1}.": "{0} toistoa jokaisessa sarjassa! Lisää yksi sarja ja palaa lukuun {1}.",
  "{0} sets of {1}. Time to add weight or try a harder variation.": "{0} sarjaa × {1}. Aika lisätä painoa tai kokeilla vaativampaa variaatiota.",
  "{0} per side": "{0} puolta kohti",
  "Per side": "Puolta kohti",
  "You still log the total: {0} is {1} per side.": "Kirjaat silti kokonaismäärän: {0} on {1} puolta kohti.",
  "Could not ask the Coach": "Valmentajalta ei voitu kysyä",
