  "Undo the last Coach changes?": "Kumotaanko valmentajan viimeisimmät muutokset?",
  "Your plan goes back to how it was before you accepted them. Workouts you have logged since are untouched.": "Suunnitelmasi palautuu siihen, millainen se oli ennen muutosten hyväksymistä. Sen jälkeen kirjatut treenit säilyvät ennallaan.",
