  "Your name, your sign-in details and everything else about your account stay here. Other people’s data is never included.": "Nimesi, kirjautumistietosi ja kaikki muut tilitietosi pysyvät täällä. Muiden tietoja ei koskaan liitetä mukaan.",
  "The Coach is not a doctor or a physiotherapist. If something hurts, ask a professional.": "Valmentaja ei ole lääkäri eikä fysioterapeutti. Jos johonkin sattuu, kysy ammattilaiselta.",
