  "You are only notified when the Coach actually has something to suggest.": "Saat ilmoituksen vain, kun valmentajalla on oikeasti jotain ehdotettavaa.",
  "On this phone the Coach can only look while the app is open: right after a workout, or the next time you open it.": "Tässä puhelimessa valmentaja voi katsoa tilanteen vain sovelluksen ollessa auki: heti treenin jälkeen tai kun seuraavan kerran avaat sovelluksen.",
