  "min": "min",
  "The Coach fits the volume to the time you actually have, including rest between sets.": "Valmentaja sovittaa volyymin käytettävissäsi olevaan aikaan, sarjojen väliset tauot mukaan lukien.",
  "What can you train with?": "Millä välineillä voit treenata?",
  "Pick everything you have access to. Leave it empty and the Coach will use the whole library.": "Valitse kaikki käytettävissäsi olevat välineet. Jos jätät tämän tyhjäksi, valmentaja käyttää koko liikepankkia.",
  "Anything to work around?": "Onko jotain huomioitavaa?",
  "Injuries, joints that complain, movements you cannot do, or practical limits like training at 6am in a flat.": "Vammoja, oireilevia niveliä, liikkeitä joita et pysty tekemään tai käytännön rajoitteita, kuten treenaaminen klo 6 kerrostaloasunnossa.",
  "e.g. “dodgy left shoulder, no barbell overhead press”": "esim. ”arka vasen olkapää, ei pystypunnerrusta levytangolla”",
  "If something actually hurts, see a professional. The Coach will program conservatively, but it can’t diagnose anything.": "Jos jokin oikeasti sattuu, käy ammattilaisen luona. Valmentaja tekee ohjelman varovaisesti, mutta ei voi tehdä diagnooseja.",
  "Anything else?": "Vielä jotain?",
