  "Name it after where you train (like \"Home\" or \"Gym\"), then tick what you’ve got there.": "Nimeä se treenipaikkasi mukaan (kuten ”Koti” tai ”Sali”) ja valitse, mitä välineitä siellä on.",
  "Profile name": "Profiilin nimi",
  "Body-weight exercises are always available, unless they need a pull-up bar or a bench.": "Kehonpainoliikkeet ovat aina käytettävissä, elleivät ne vaadi leuanvetotankoa tai penkkiä.",
