  "Filters the exercise library and picker, and flags routine exercises that need something you don’t have in the active profile.": "Suodattaa liikekirjastoa ja -valitsinta sekä merkitsee ohjelman liikkeet, jotka vaativat jotakin, mitä aktiivisessa profiilissasi ei ole.",
