  "Sync this device to your own self-hosted openGym instead.": "Synkronoi tämä laite sen sijaan omaan itse isännöityyn openGym-palvelimeesi.",
  "Pair the mobile app": "Parita mobiilisovellus",
  "Connect the openGym app on your phone to this account.": "Yhdistä puhelimesi openGym-sovellus tähän tiliin.",
  "On the openGym app, choose “Connect to my server”, then enter this address and the code below. It expires in 5 minutes.": "Valitse openGym-sovelluksessa ”Yhdistä omaan palvelimeen” ja syötä sitten tämä osoite ja alla oleva koodi. Se vanhenee 5 minuutissa.",
