  "Top sets logged without an effort rating; add RIR so the next review can read how hard they were.": "Huippusarjat on kirjattu ilman rasitusarviota; lisää RIR, jotta seuraava katsaus näkee, kuinka raskaita ne olivat.",
  "Add the next load step on the main lift.": "Lisää seuraava painoporras pääliikkeeseen.",
  "Repeat the same loads and get every set.": "Toista samat painot ja tee kaikki sarjat täyteen.",
  "Keep the session under an hour and a quarter.": "Pidä treenikerta alle tunnissa ja vartissa.",
  "A clean session: everything on the sheet got done and the loads held. This is exactly what progress looks like from the inside: unremarkable, repeated.": "Puhdas treenikerta: kaikki suunniteltu tuli tehtyä ja painot pitivät. Juuri tältä kehitys näyttää sisältäpäin: arkiselta ja toistuvalta.",
  "Most of the work got done. One or two sets fell short, which is fine once. It only becomes a signal if the same sets miss next time.": "Suurin osa työstä tuli tehtyä. Yksi tai kaksi sarjaa jäi vajaaksi, mikä ei haittaa kerran. Se on merkki vasta, jos samat sarjat jäävät vajaiksi seuraavallakin kerralla.",
