  "Every stored weight (logged sets, working weights, routine targets, body weight, bar weights) is in {0}. Convert the numbers, or keep them and only change the label?": "Kaikki tallennetut painot (kirjatut sarjat, työpainot, ohjelman tavoitteet, kehonpaino, tankojen painot) ovat yksikössä {0}. Muunnetaanko luvut vai pidetäänkö ne ennallaan ja vaihdetaan vain yksikön merkintä?",
  "Convert the numbers": "Muunna luvut",
  "Keep the numbers, change the label": "Pidä luvut, vaihda merkintä",
  "Switching the unit offers to convert every stored weight.": "Yksikköä vaihdettaessa tarjotaan kaikkien tallennettujen painojen muuntamista.",
  "Update to {0}?": "Päivitetäänkö versioon {0}?",
