  "Log your body weight to score this lift.": "Kirjaa kehonpainosi, jotta tämä nosto voidaan pisteyttää.",
  "Log the anchor lift to score this one.": "Kirjaa vertailuliike, jotta tämä voidaan pisteyttää.",
