  "The server cannot be reached": "Palvelimeen ei saada yhteyttä",
  "Your server can’t be reached. Your changes are saved on this device and sync once it answers again.": "Palvelimeesi ei saada yhteyttä. Muutoksesi tallennetaan tälle laitteelle, ja ne synkronoidaan, kun palvelin taas vastaa.",
  "Your server can’t be reached. Showing the last copy synced with it.": "Palvelimeesi ei saada yhteyttä. Näytetään viimeisin sen kanssa synkronoitu kopio.",
  "Server address unknown": "Palvelimen osoite tuntematon",
  "Pair again, or export a backup first. Going ahead anyway keeps a copy of these changes on this device until it connects to this server as this account again. Then they’re added back.": "Muodosta laitepari uudelleen tai vie ensin varmuuskopio. Jos jatkat tästä huolimatta, muutoksista säilytetään kopio tällä laitteella, kunnes se yhdistää uudelleen tähän palvelimeen tällä tilillä. Silloin ne lisätään takaisin.",
