  "The server has {0} workouts that are not in this backup, logged since it was made or on another device. Replacing deletes them.": "Palvelimella on {0} treeniä, joita ei ole tässä varmuuskopiossa. Ne on kirjattu varmuuskopion luomisen jälkeen tai toisella laitteella. Korvaaminen poistaa ne.",
