  "The Coach hit its AI provider’s limit. Try again later, or the instance owner needs to check the plan or key.": "Valmentaja saavutti AI-palveluntarjoajansa rajan. Yritä myöhemmin uudelleen, tai instanssin ylläpitäjän täytyy tarkistaa tilaus tai avain.",
