  "{0} photos": "{0} kuvaa",
  "Your server was reached, but it refused the app’s request (CORS). If a reverse proxy such as Traefik adds CORS headers, let requests from {0} through to openGym unchanged. See “Phone app and CORS” in docs/SELF_HOSTING.md.": "Palvelimeen saatiin yhteys, mutta se hylkäsi sovelluksen pyynnön (CORS). Jos käänteinen välityspalvelin, kuten Traefik, lisää CORS-otsakkeet, päästä pyynnöt osoitteesta {0} läpi openGymiin muuttumattomina. Katso ”Phone app and CORS” tiedostosta docs/SELF_HOSTING.md.",
  "Could not reach {0}. Check the address and that this phone can reach it.": "Osoitteeseen {0} ei saatu yhteyttä. Tarkista osoite ja varmista, että tämä puhelin tavoittaa sen.",
