  "Show connection status": "Näytä yhteyden tila",
  "Off: the bar at the top is hidden. A dot on Home still warns when syncing is stuck.": "Pois päältä: yläpalkki on piilotettu. Etusivun piste varoittaa silti, jos synkronointi jumittaa.",
  "Connection problem": "Yhteysongelma",
  "Backup folder": "Varmuuskopiokansio",
  "Chosen folder": "Valittu kansio",
  "Use default folder": "Käytä oletuskansiota",
  "This folder can’t be used for backups.": "Tätä kansiota ei voi käyttää varmuuskopioihin.",
  "openGym can no longer write to “{0}”, so copies go to Documents/openGym again. Choose the folder again to switch back.": "openGym ei voi enää kirjoittaa kansioon ”{0}”, joten kopiot tallentuvat taas kansioon Documents/openGym. Valitse kansio uudelleen vaihtaaksesi takaisin.",
  "openGym can no longer write to the chosen folder, so copies go to Documents/openGym again. Choose the folder again to switch back.": "openGym ei voi enää kirjoittaa valittuun kansioon, joten kopiot tallentuvat taas kansioon Documents/openGym. Valitse kansio uudelleen vaihtaaksesi takaisin.",
  "Nudge me when I skip a planned workout": "Muistuta, jos jätän suunnitellun treenin väliin",
  "Nudge tone": "Muistutusten sävy",
  "Friendly": "Ystävällinen",
  "Guilt trip": "Syyllistävä",
  "Drill sergeant": "Kersantti",
  "One nudge in the evening of a planned day with nothing logged, between 20:00 and 21:30. After 3 missed days in a row it goes quiet until your next workout.": "Yksi muistutus suunnitellun treenipäivän iltana klo 20.00–21.30, jos mitään ei ole kirjattu. Kolmen peräkkäisen väliin jääneen päivän jälkeen muistutukset vaikenevat seuraavaan treeniin asti.",
  "Logged a workout on another device? Before the nudge goes out, the phone checks with your server whenever it lets the app run in the background. Opening the app always catches up.": "Kirjasitko treenin toisella laitteella? Ennen muistutuksen lähettämistä puhelin tarkistaa tilanteen palvelimeltasi aina, kun sovellus saa toimia taustalla. Sovelluksen avaaminen päivittää tiedot aina ajan tasalle.",
  "Everything okay?": "Kaikki hyvin?",
  "{0} is still waiting. What’s up?": "{0} odottaa yhä. Mikä meininki?",
  "No {0} today? Even a short session tomorrow counts.": "Jäikö {0} tänään väliin? Lyhytkin treenikerta huomenna lasketaan.",
  "Rough day? {0} will keep. Tomorrow is a fresh start.": "Rankka päivä? {0} kyllä odottaa. Huomenna on uusi alku.",
  "Hey, {0} didn’t happen today. All good?": "Hei, {0} jäi tänään tekemättä. Kaikki ok?",
  "I miss you": "Ikävä sinua",
  "{0} waited by the door all evening. For you.": "{0} odotti ovella koko illan. Juuri sinua.",
  "The barbell asked about you today. I didn’t know what to say.": "Levytanko kyseli tänään perääsi. En tiennyt mitä sanoa.",
  "Was it something I said? {0} misses you.": "Sanoinko jotain väärin? {0} kaipaa sinua.",
  "I saved you a spot on the bench. It’s still empty.": "Varasin sinulle paikan penkiltä. Se on yhä tyhjä.",
  "Attention, recruit!": "Huomio, alokas!",
  "Your gains are packing their bags. {0} tomorrow, no excuses!": "Tuloksesi pakkaavat jo laukkujaan. Huomenna {0}, ei tekosyitä!",
  "{0} doesn’t do itself, recruit. Move it!": "{0} ei tee itseään, alokas. Liikettä niveliin!",
  "Excuses don’t lift weights. Report for {0} tomorrow!": "Tekosyyt eivät rautaa nosta. Ilmoittaudu huomenna: {0}!",
  "Your muscles filed a missing-person report. Show up for {0}!": "Lihaksesi tekivät sinusta katoamisilmoituksen. Ilmesty paikalle: {0}!",
  "That address answers, but it isn’t an openGym server. Check the URL.": "Osoite vastaa, mutta se ei ole openGym-palvelin. Tarkista URL-osoite.",
  "That address answers, but a login page or proxy rule replied instead of openGym. Let /api/ through to openGym unchanged. See “Phone app and CORS” in docs/SELF_HOSTING.md.": "Osoite vastaa, mutta openGymin sijaan vastasi kirjautumissivu tai välityspalvelimen sääntö. Päästä /api/ läpi openGymiin muuttumattomana. Katso ”Phone app and CORS” tiedostosta docs/SELF_HOSTING.md.",
  "Switch sides": "Vaihda puolta",
  "Saves a dated copy to “{0}” after finishing a workout or editing a routine, and keeps the newest {1}.": "Tallentaa päivätyn kopion kansioon ”{0}” treenin päättämisen tai ohjelman muokkauksen jälkeen ja säilyttää {1} uusinta.",
  "Saves a dated copy to the folder you chose after finishing a workout or editing a routine, and keeps the newest {0}.": "Tallentaa päivätyn kopion valitsemaasi kansioon treenin päättämisen tai ohjelman muokkauksen jälkeen ja säilyttää {0} uusinta.",
  "Plan options": "Suunnitelman vaihtoehdot",
  "Your routines in a loop": "Ohjelmasi kierrossa",
  "Back to a fixed week?": "Palataanko kiinteään viikkoon?",
  "The loop stops. Your weekdays stay as they are, and the loop is saved for later.": "Kierto pysähtyy. Viikonpäiväsi pysyvät ennallaan, ja kierto tallennetaan myöhempää varten.",
  "Routines in a loop. Whatever is next stays next until you train it, whatever the day.": "Ohjelmat kierrossa. Seuraavana vuorossa oleva pysyy seuraavana kunnes treenaat sen, viikonpäivästä riippumatta.",
  "The same routines on the same weekdays, every week.": "Samat ohjelmat samoina viikonpäivinä, joka viikko.",
  "How you train": "Miten treenaat",
  "Want two routines on one day? Tap the day and pick both.": "Haluatko kaksi ohjelmaa samalle päivälle? Napauta päivää ja valitse molemmat.",
