  "Weight means": "Paino tarkoittaa",
  "The weight of the one you hold. One arm, so it counts once.": "Kädessäsi olevan käsipainon painoa. Yksi käsi, joten se lasketaan kerran.",
  "The weight of one, so 20 means 20 in each hand. Volume counts both.": "Yhden käsipainon painoa, joten 20 tarkoittaa 20 kg kummassakin kädessä. Volyymi laskee molemmat.",
  "Both together, so 40 means two 20s.": "Molempia yhdessä, joten 40 tarkoittaa kahta 20 kg:n painoa.",
  "Counted as you type it, the way it always was.": "Lasketaan sellaisenaan kuin kirjoitat sen, kuten ennenkin.",
  "You’ve outgrown the rack: {0} {1} is your heaviest dumbbell, so the weight stays.": "Telineen painot loppuivat kesken: {0} {1} on painavin käsipainosi, joten paino pysyy samana.",
  "Dumbbells": "Käsipainot",
  "The weights you own, one bell each. Progression, deloads, warm-ups and the + and − buttons of dumbbell lifts land only on these.": "Omistamasi painot, yksi käsipaino kutakin. Progressio, kevennykset, lämmittelyt sekä käsipainoliikkeiden painikkeet + ja − osuvat vain näihin.",
  "No list yet, so dumbbell lifts step by their increment as usual.": "Ei listaa vielä, joten käsipainoliikkeet etenevät tavallisella korotuksella.",
  "Fill in {0} to {1} {2}, every {3}": "Täytä {0}–{1} {2}, {3} välein",
  "Clear the list": "Tyhjennä lista",
  "Any weight. Tap to list the ones you own.": "Mikä tahansa paino. Napauta listataksesi omistamasi.",
  "F": "F",
  "Taken to failure": "Tehty uupumukseen",
  "Nothing left in the tank": "Tankki täysin tyhjä",
  "Last set to failure": "Viimeinen sarja uupumukseen",
  "The last set goes until nothing is left, and counts as all-out effort unless you rate it.": "Viimeinen sarja tehdään uupumukseen asti, ja se lasketaan täydeksi rasitukseksi, ellet arvioi sitä itse.",
  "Plan the final set as an all-out one.": "Suunnittele viimeinen sarja tehtäväksi täysillä loppuun asti.",
  "Triple progression": "Kolmoisprogressio",
  "Reps climb to the top of the range, then a set is added, up to your most sets. All of them at the top and the weight goes up, back to your first sets and reps.": "Toistot nousevat alueen ylärajaan, minkä jälkeen lisätään sarja enimmäismäärään saakka. Kun kaikki sarjat ovat ylärajassa, paino nousee ja palaat alkuperäisiin sarjoihin ja toistoihin.",
  "Same weight, aim for {0} reps in every set.": "Sama paino, tavoitteena {0} toistoa jokaisessa sarjassa.",
  "Same weight, aim for {0} reps on the last set.": "Sama paino, tavoitteena {0} toistoa viimeisessä sarjassa.",
  "{0} reps in every set! Add a set at {1} reps.": "{0} toistoa joka sarjassa! Lisää yksi sarja {1} toistolla.",
  "Top of the range on all {0} sets. {1} {2} more, back to {3} sets of {4}.": "Yläraja saavutettu kaikissa {0} sarjassa. {1} {2} lisää, paluu {3} sarjaan, {4} toistoa.",
  "Top of the range on all {0} sets. {1} {2} less help, back to {3} sets of {4}.": "Yläraja saavutettu kaikissa {0} sarjassa. {1} {2} vähemmän avustusta, paluu {3} sarjaan, {4} toistoa.",
  "Short of the target, but more reps than before. Same sets and reps again.": "Tavoite jäi vajaaksi, mutta toistoja tuli enemmän kuin viimeksi. Samat sarjat ja toistot uudelleen.",
  "Missed reps last time. Same sets and reps again ({0} of {1} to go).": "Toistot jäivät vajaiksi viimeksi. Samat sarjat ja toistot uudelleen ({0}/{1} jäljellä).",
  "Stuck for {0} sessions. Deload to {1} {2} and start again at {3} sets of {4}.": "Paikallaan {0} treenikerran ajan. Kevennä painoon {1} {2} ja aloita alusta: {3} sarjaa, {4} toistoa.",
  "Stuck for {0} sessions. Back to {1} {2} of help, start again at {3} sets of {4}.": "Paikallaan {0} treenikerran ajan. Takaisin {1} {2} avustukseen, aloita alusta: {3} sarjaa, {4} toistoa.",
