  "Through your server": "Palvelimesi kautta",
  "To answer, the Coach sends this through your openGym server to {0}, an AI service outside openGym that your server’s admin picked:": "Vastatakseen Valmentaja lähettää nämä openGym-palvelimesi kautta palveluun {0}, joka on palvelimesi ylläpitäjän valitsema ulkopuolinen tekoälypalvelu:",
  "To answer, this device sends this straight to {0}, an AI service outside openGym, with your API key:": "Vastatakseen tämä laite lähettää nämä suoraan API-avaimellasi palveluun {0}, joka on openGymin ulkopuolinen tekoälypalvelu:",
  "Who may see your training": "Kuka saa nähdä treenisi",
  "Who the Coach may send your training to from this device. Withdraw it and the Coach asks again next time. A model on your own network never needs asking.": "Kenelle Valmentaja saa lähettää treenisi tältä laitteelta. Jos perut luvan, Valmentaja kysyy ensi kerralla uudelleen. Omassa verkossasi toimiva malli ei koskaan kysy lupaa.",
