  "Delete my account": "Poista tilini",
  "Removes your profile and everything in it from this server.": "Poistaa profiilisi ja kaiken sen sisällön tältä palvelimelta.",
  "Delete your account?": "Poistetaanko tilisi?",
  "Your profile, workouts, body weight, photos and videos are deleted from this server for good. There is no undo, and not even your admin can bring them back.": "Profiilisi, treenisi, kehonpainosi, kuvasi ja videosi poistetaan tältä palvelimelta pysyvästi. Tätä ei voi perua, eikä edes ylläpitäjäsi pysty palauttamaan niitä.",
  "Want a copy first? Export a backup. You can import it into openGym anytime.": "Haluatko ensin kopion? Vie varmuuskopio. Voit tuoda sen openGym-sovellukseen milloin tahansa.",
  "Type {0} to confirm.": "Vahvista kirjoittamalla {0}.",
  "Account name": "Tilin nimi",
  "Delete forever": "Poista pysyvästi",
  "That is not your account name.": "Tuo ei ole tilisi nimi.",
  "You’re the only admin here, and other profiles still use this server. Make someone else an admin first.": "Olet ainoa ylläpitäjä täällä, ja muut profiilit käyttävät yhä tätä palvelinta. Tee ensin jostakusta muusta ylläpitäjä.",
  "Couldn’t delete the account. Nothing was removed.": "Tilin poisto epäonnistui. Mitään ei poistettu.",
  "Your account is gone. Thanks for every rep.": "Tilisi on nyt poissa. Kiitos jokaisesta toistosta.",
  "Confirm it’s you to delete your openGym account": "Vahvista henkilöllisyytesi poistaaksesi openGym-tilisi",
  "Not confirmed on this phone. Nothing was deleted.": "Ei vahvistettu tällä puhelimella. Mitään ei poistettu.",
  "This phone has no screen lock, so the name you typed is the only check.": "Tässä puhelimessa ei ole näytönlukitusta, joten kirjoittamasi nimi on ainoa varmistus.",
  "Your phone checks that it’s you (face, fingerprint or passcode), then the account is deleted.": "Puhelimesi varmistaa henkilöllisyytesi (kasvot, sormenjälki tai pääsykoodi), ja sitten tili poistetaan.",
  "Never miss the end of a rest": "Älä koskaan ohita tauon loppua",
