  "You can change it anytime in your phone’s settings.": "Voit muuttaa tätä milloin tahansa puhelimesi asetuksista.",
  "openGym can tap you on the shoulder when a rest is over, even with the phone locked in your pocket.": "openGym voi koputtaa sinua olkapäälle, kun tauko on ohi, vaikka puhelin olisi lukittuna taskussasi.",
