  "Sharper animations download once per figure. Until they’re here you see the built-in ones, so nothing ever goes blank.": "Tarkemmat animaatiot ladataan kerran kutakin hahmoa kohden. Siihen asti näet sisäänrakennetut, joten mikään ei jää tyhjäksi.",
