  "Warm-ups are light, so they can rest less, or not at all. The last one still gets the full rest before your first work set.": "Lämmittelysarjat ovat kevyitä, joten niiden välissä voi pitää lyhyemmän tauon tai ei taukoa lainkaan. Viimeisen jälkeen pidetään silti täysi tauko ennen ensimmäistä työsarjaa.",
  "Add photos": "Lisää kuvia",
