  "No progress photos yet. Add one for today or any day before.": "Ei edistymiskuvia vielä. Lisää kuva tälle päivälle tai mille tahansa aiemmalle päivälle.",
  "The photo says it was taken on {0}. Change the day if it was another one.": "Kuvan tietojen mukaan se on otettu {0}. Vaihda päivä, jos se oli jokin muu.",
