  "This app can’t confirm with a passkey. Make the code in a browser signed in to this profile, or add a password there first.": "Tämä sovellus ei voi vahvistaa pääsyavaimella. Luo koodi tähän profiiliin kirjautuneessa selaimessa tai lisää siellä ensin salasana.",
