  "What the bars at your gym weigh. Every exercise with that bar counts plates from it, unless you gave the exercise its own. Logged weights stay totals.": "Salisi tankojen painot. Jokainen kyseistä tankoa käyttävä liike laskee levypainot tästä painosta, ellet ole asettanut liikkeelle omaa tankoa. Kirjatut painot säilyvät kokonaispainoina.",
  "Most lifts in the library use “{0}”, a few use “{1}”. A short bar for all of them means setting both.": "Useimmat kirjaston liikkeet käyttävät tyyppiä ”{0}”, muutama tyyppiä ”{1}”. Jos haluat lyhyen tangon kaikkiin, aseta molemmat.",
