  "Not trained:": "Ei treenattu:",
  "Rounded to whole sets. A set counts fully for its main muscle and partly for the ones that help, so the muscles add up to more than your work sets.": "Pyöristetty kokonaisiin sarjoihin. Sarja lasketaan kokonaan päälihakselle ja osittain avustaville lihaksille, joten lihasten sarjamäärät summautuvat työsarjoja suuremmiksi.",
  "One session in this period.": "Yksi treenikerta tällä jaksolla.",
  "No workouts in this period.": "Ei treenejä tällä jaksolla.",
