  "All workouts": "Kaikki treenit",
  "Performance report": "Suoritusraportti",
  "Your training on paper: totals, charts, new bests and every set. Frame it, print it or send it to your coach.": "Treenisi paperilla: yhteenvedot, kaaviot, uudet ennätykset ja jokainen sarja. Kehystä se, tulosta tai lähetä valmentajallesi.",
  "7 days": "7 päivää",
  "4 weeks": "4 viikkoa",
