  "Strength block, 4 weeks": "Voimajakso, 4 viikkoa",
  "The schedule in your plan right now becomes this programme’s.": "Suunnitelmasi nykyinen aikataulu tulee tämän treenijakson aikatauluksi.",
  "The week is the calendar week: week 1 is the one you start in. A pause holds it.": "Viikko on kalenteriviikko: viikko 1 on se, jolla aloitat. Tauko pitää sen paikallaan.",
  "This programme is gone.": "Tätä treenijaksoa ei enää ole.",
