  "Try the Halloween app icon": "Kokeile Halloween-sovelluskuvaketta",
  "Is that right?": "Onko tämä oikein?",
  "Weight: {0} is more than twice your heaviest, {1}.": "Paino: {0} on yli tuplasti enemmän kuin raskain tuloksesi, {1}.",
  "Reps: {0} is more than twice your most, {1}.": "Toistot: {0} on yli tuplasti enemmän kuin paras tuloksesi, {1}.",
  "Weight: {0} is under a third of last time’s {1}.": "Paino: {0} on alle kolmasosa viime kerran painosta {1}.",
