  "Workouts, routines and weigh-ins, once.": "Treenit, ohjelmat ja punnitukset, kerran.",
  "The key is used for this import and then forgotten.": "Avainta käytetään tähän tuontiin, ja sen jälkeen se unohdetaan.",
  "Import a file": "Tuo tiedosto",
