  "Reads the export file of another app, once.": "Lukee toisen sovelluksen vientitiedoston kerran.",
  "Exercises are matched to the library, you check the rest.": "Liikkeet yhdistetään kirjastoon, sinä tarkistat loput.",
  "Spreadsheet (CSV)": "Taulukko (CSV)",
  "Every set, weigh-in and measurement, for Excel and friends.": "Jokainen sarja, punnitus ja mittaus, Excelille ja kumppaneille.",
  "One row per set, plus body weight and measurements.": "Yksi rivi sarjaa kohden sekä kehonpaino ja mitat.",
  "openGym can read it back in later.": "openGym osaa lukea sen takaisin myöhemmin.",
  "Tell Home Assistant, n8n or ntfy when you finish a workout.": "Ilmoita Home Assistantille, n8n:lle tai ntfy:lle, kun lopetat treenin.",
  "A signed JSON message when a workout is finished, a record falls or you weigh in.": "Allekirjoitettu JSON-viesti, kun treeni on valmis, ennätys rikkoutuu tai kirjaat punnituksen.",
  "Sent by your server, from whichever device you logged on.": "Palvelimesi lähettää sen riippumatta siitä, millä laitteella kirjasit tiedot.",
