  "Monthly challenges": "Kuukausihaasteet",
  "Three goals a month on Home, sized to how you train.": "Kolme kuukausitavoitetta Koti-näkymässä, treenitahtiisi mitoitettuna.",
  "Plain http:// only works for an address on your home network, like 192.168.x.x, a .local name or a Tailscale 100.x address. Anything on the internet needs https://.": "Pelkkä http:// toimii vain kotiverkkosi osoitteissa, kuten 192.168.x.x, .local-nimissä tai Tailscalen 100.x-osoitteissa. Kaikki internetissä oleva vaatii https://-yhteyden.",
  "Plain http only on your home network": "Pelkkä http vain kotiverkossa",
  "Freestyle repeats what you did last time, with no progression rule. Rules apply to exercises in a routine.": "Vapaa treeni toistaa viime kerran lukemat ilman progressiosääntöä. Säännöt koskevat ohjelman liikkeitä.",
