  "Built from your work weight and rounded to this gym’s plates and dumbbells. An exercise can pick its own in its settings.": "Lasketaan työsarjapainostasi ja pyöristetään tämän salin levypainojen ja käsipainojen mukaan. Liikkeelle voi valita oman asetuksen sen asetuksista.",
