  "Each one closes half the gap to the work weight.": "Jokainen sarja puolittaa matkan työsarjapainoon.",
  "Every loaded lift": "Kaikki painolliset liikkeet",
  "Feeling great": "Loistava olo",
  "Follows Settings → Workout → Automatic warm-ups.": "Noudattaa polkua Asetukset → Treeni → Automaattiset lämmittelyt.",
  "For this workout": "Tähän treeniin",
  "Heavy lifts get more rungs, light ones one or none.": "Raskaat liikkeet saavat enemmän portaita, kevyet yhden tai eivät yhtään.",
  "It hurts": "Sattuu",
  "It hurts, it’s taken, no time, feeling great": "Sattuu, varattu, ei aikaa, vahva olo",
  "It pinches, so lighter for the rest of it. Stop if it still hurts.": "Nipistää, joten tehdään loppu kevyemmin. Lopeta, jos sattuu edelleen.",
  "It pinches, so the sets you have left go to a movement that loads the same muscle from a kinder angle.": "Nipistää, joten jäljellä olevat sarjat tehdään liikkeellä, joka kuormittaa samaa lihasta lempeämmästä kulmasta.",
  "Keep these warm-ups": "Säilytä nämä lämmittelyt",
  "Kept. Same warm-ups next time, scaled to your work weight.": "Säilytetty. Samat lämmittelyt ensi kerralla, skaalattuna työpainoosi.",
  "Logged sets and your routine stay as they are. The Coach is not a doctor or a physiotherapist. If something hurts, ask a professional.": "Kirjatut sarjat ja ohjelmasi pysyvät ennallaan. Valmentaja ei ole lääkäri eikä fysioterapeutti. Jos jokin sattuu, kysy ammattilaiselta.",
  "Looking at your workout…": "Tutkin treeniäsi…",
