  "My own": "Omat",
  "New programme “{0}”": "Uusi harjoitusohjelma ”{0}”",
  "Nothing at {0} {1}: that one starts cold.": "Ei mitään painolla {0} {1}: se alkaa kylmiltään.",
  "Nothing could be applied any more.": "Mitään ei voitu enää ottaa käyttöön.",
