  "Routines, exercises, sets and reps, warm-ups, programmes, your weekly schedule, progression settings and what your gym can load.": "Ohjelmat, liikkeet, sarjat ja toistot, lämmittelyt, harjoitusohjelmat, viikkoaikataulusi, nousujohteisuusasetukset ja salisi painovalikoima.",
  "Running on empty": "Takki tyhjänä",
