  "Short on time": "Aika vähissä",
  "Skip the rest of {0}": "Ohita loput liikkeestä {0}",
  "Something else": "Jotain muuta",
  "Squats, presses, rows and friends get a ramp. Curls and raises start cold.": "Kyykyt, punnerrukset, soudut ja kumppanit saavat portaat. Käännöt ja nostot aloitetaan kylmiltään.",
