  "That workout is over, so these can’t be applied any more.": "Se treeni on jo ohi, joten näitä ei voi enää ottaa käyttöön.",
  "The app ramps up from your work weight: more warm-up sets when it is heavy, fewer when it is light, on your gym’s plates.": "Sovellus porrastaa työpainostasi: enemmän lämmittelysarjoja raskailla painoilla ja vähemmän kevyillä, salisi levypainoilla.",
  "The rack is taken, so do it at the end. The rest of the session does not need it.": "Teline on varattu, joten tee tämä lopuksi. Muu treenikerta ei tarvitse sitä.",
  "There’s no workout running.": "Treeniä ei ole käynnissä.",
  "These warm-ups come before the work sets every session, as a share of the work weight, so they grow with it.": "Nämä lämmittelyt tulevat ennen työsarjoja joka treenikerralla osuutena työpainosta, joten ne kasvavat sen mukana.",
  "This is the demo, so there is no AI model behind me. On your own server I read your session and suggest changes like these.": "Tämä on demo, joten taustallani ei ole tekoälymallia. Omalla palvelimellasi luen treenikertasi ja ehdotan tällaisia muutoksia.",
