  "Bank 1 freeze, earned every 4 trained weeks. Two missed weeks in a row end the streak.": "Säästä 1 jäädytys, ansaitset yhden joka 4. treeniviikolta. Kaksi väliin jäänyttä viikkoa peräkkäin katkaisee putken.",
