  "That file can never be shared here. Pictures and animations from the built-in library are licensed.": "Tätä tiedostoa ei voi koskaan jakaa täällä. Sisäänrakennetun kirjaston kuvat ja animaatiot ovat lisensoituja.",
  "That file still carries hidden details like a location. Add it again in the app and share the new copy.": "Tiedostossa on yhä piilotettuja tietoja, kuten sijainti. Lisää se uudelleen sovelluksessa ja jaa uusi kopio.",
