  "That sound did not come through.": "Ääni ei tullut perille.",
  "That tip did not come through.": "Vinkki ei tullut perille.",
  "The sharing text changed. Have a quick read and try again.": "Jakoteksti on muuttunut. Lukaise se läpi ja yritä uudelleen.",
  "This is public to everyone on this server: everyone with an account here can see it, try it and copy it. Your name and the date go with it, always. Only share what is yours: something you made, recorded or have the right to pass on. The exercise pictures and animations of the built-in library are licensed and can never be shared. You can stop sharing any time; copies people already took stay with them.": "Tämä näkyy julkisesti kaikille tällä palvelimella: jokainen, jolla on täällä tili, voi nähdä, kokeilla ja kopioida sen. Nimesi ja päivämäärä kulkevat aina mukana. Jaa vain sellaista, mikä on omaasi: itse tekemääsi, äänittämääsi tai sellaista, jonka jakamiseen sinulla on oikeus. Sisäänrakennetun kirjaston liikekuvat ja -animaatiot ovat lisensoituja, eikä niitä voi koskaan jakaa. Voit lopettaa jakamisen milloin tahansa; muiden jo ottamat kopiot jäävät heille.",
  "This kind of item cannot be taken.": "Tällaista kohdetta ei voi ottaa.",
