  "Your exercises can move at {0} px instead of {1} px, crisp on this screen.": "Liikkeesi voivat toistua tarkkuudella {0} px ({1} px sijaan), terävästi tällä näytöllä.",
  "A one-time download of about {0} from Google Play, over Wi-Fi. It stays on this phone.": "Kertaluontoinen lataus Google Playsta Wi-Fi-yhteydellä (noin {0}). Se pysyy tällä puhelimella.",
