  "Download": "Lataa",
  "Changed your mind? Settings has it, any time.": "Muutitko mieltäsi? Löydät sen Asetuksista milloin vain.",
  "A profile here already uses that e-mail. Sign in to it another way, then link {0} in Settings.": "Yksi profiili täällä käyttää jo tuota sähköpostia. Kirjaudu siihen muulla tavalla ja linkitä {0} sitten Asetuksissa.",
