  "Link your {0} account and sign in with it from now on. Your passkeys keep working too. First a quick check that this is really you.": "Linkitä {0}-tilisi ja kirjaudu sillä tästä lähtien. Pääsyavaimesi toimivat edelleen. Tarkistetaan ensin nopeasti, että olet todella sinä.",
  "Linked. You can sign in with {0} from now on.": "Linkitetty. Voit kirjautua jatkossa {0}-tilillä.",
