  "Sign in with {0}": "Kirjaudu palvelulla {0}",
  "Sign-in cancelled. No harm done.": "Kirjautuminen peruttu. Ei hätää.",
  "That sign-in took too long or came from another tab. Give it another go.": "Kirjautuminen kesti liian kauan tai tuli toiselta välilehdeltä. Yritä uudelleen.",
  "That was a different {0} account than the one linked to this profile.": "Tuo oli eri {0}-tili kuin tähän profiiliin linkitetty.",
