  "This profile is linked to your {0} account, so signing in there signs you in here.": "Tämä profiili on linkitetty {0}-tiliisi, joten kirjautuminen siellä kirjaa sinut myös tänne.",
  "This server is invite-only and {0} alone does not get you in. Ask whoever runs it.": "Tämä palvelin toimii vain kutsulla, eikä pelkkä {0} riitä sisäänpääsyyn. Kysy palvelimen ylläpitäjältä.",
  "This server signs everyone in with {0}. New here? Signing in makes your profile.": "Tällä palvelimella kaikki kirjautuvat palvelulla {0}. Uusi täällä? Kirjautuminen luo profiilisi.",
  "This server signs people in with {0}.": "Tällä palvelimella kirjaudutaan palvelulla {0}.",
