  "Unlink": "Poista linkitys",
  "Unlinked. {0} no longer signs you in here.": "Linkitys poistettu. {0} ei enää kirjaa sinua sisään tänne.",
  "or use a pairing code": "tai käytä pariliitoskoodia",
  "{0} could not be reached. Try again in a moment.": "Palveluun {0} ei saatu yhteyttä. Yritä hetken kuluttua uudelleen.",
  "{0} is the only way into this profile, so it stays linked. Add a passkey first.": "{0} on ainoa tapa päästä tähän profiiliin, joten se pysyy linkitettynä. Lisää ensin pääsyavain.",
  "{0} let you in, but this server only takes certain groups. Ask whoever runs it to add you.": "{0} päästi sinut sisään, mutta tämä palvelin hyväksyy vain tietyt ryhmät. Pyydä ylläpitäjää lisäämään sinut.",
  "{0} sent back something we could not verify, so nobody was signed in. If it keeps happening, the admin page shows why.": "{0} palautti jotain, mitä emme voineet vahvistaa, joten ketään ei kirjattu sisään. Jos tämä toistuu, ylläpitosivu näyttää syyn.",
  "Backups: {0}": "Varaliikkeet: {0}",
  "Suggested": "Ehdotetut",
