  "Last time and the next weight come from this gym only.": "Edellinen kerta ja seuraava paino haetaan vain tältä salilta.",
  "Brand at {0}": "Merkki salilla {0}",
  "Life Fitness, Technogym… (optional)": "Life Fitness, Technogym… (valinnainen)",
  "Same brand at another gym? It shares these numbers. Records and Stats still count every gym.": "Sama merkki toisella salilla? Silloin nämä luvut jaetaan. Ennätykset ja tilastot laskevat silti kaikki salit.",
  "For machines and cables that feel different from gym to gym. Free weights rarely need it.": "Laitteille ja taljoille, jotka tuntuvat erilaisilta eri saleilla. Vapaat painot tarvitsevat tätä harvoin.",
  "All gyms": "Kaikki salit",
  "Today’s planned rows for {0} didn’t fit, so the routine’s own are up: {1}": "Liikkeelle {0} tälle päivälle suunnitellut sarjat eivät sopineet, joten ohjelman omat ovat käytössä: {1}",
  "Today’s rows come from {0}. Your routine stays as it is.": "Tämän päivän sarjojen lähde on {0}. Ohjelmasi pysyy ennallaan.",
  "Today’s rows were planned for this day. Your routine stays as it is.": "Tämän päivän sarjat on suunniteltu tälle päivälle. Ohjelmasi pysyy ennallaan.",
  "Body composition from your scale": "Kehonkoostumus vaa’altasi",
  "Body fat and lean mass, as your scale saved them. Shown under Body measurements, never mixed into what you log.": "Kehon rasva ja rasvaton massa sellaisina kuin vaakasi ne tallensi. Näkyvät kohdassa Kehon mitat, eikä niitä koskaan sekoiteta itse kirjaamiisi tietoihin.",
  "Body fat, lean mass, bone mass, body water and BMR, as your scale saved them. Shown under Body measurements, never mixed into what you log.": "Kehon rasva, rasvaton massa, luumassa, kehon vesi ja perusaineenvaihdunta sellaisina kuin vaakasi ne tallensi. Näkyvät kohdassa Kehon mitat, eikä niitä koskaan sekoiteta itse kirjaamiisi tietoihin.",
