  "A buzz for each phase": "Värinä jokaiselle vaiheelle",
  "A copy of everything, once a day, in a folder of your own: Nextcloud, ownCloud, a NAS, anything that speaks WebDAV. Your server, nobody else’s.": "Kopio kaikesta kerran päivässä omaan kansioosi: Nextcloud, ownCloud, NAS tai mikä tahansa WebDAV-palvelin. Sinun palvelimesi, ei kenenkään muun.",
  "A sound for each kind of rest": "Ääni jokaiselle taukotyypille",
  "A tick on every day you trained, with how many sets. Only you see it, the same as the plan.": "Merkintä jokaiselle treenipäivälle, mukana sarjamäärä. Vain sinä näet sen, samoin kuin suunnitelman.",
  "A tone for each phase": "Äänimerkki jokaiselle vaiheelle",
  "Again": "Uudelleen",
  "An app password is best": "Sovellussalasana toimii parhaiten",
