  "Lift (s)": "Nosto (s)",
  "Squeeze at the top (s)": "Puristus ylhäällä (s)",
  "The server did not take that name and password. An app password usually works best.": "Palvelin ei hyväksynyt tätä nimeä ja salasanaa. Sovellussalasana toimii yleensä parhaiten.",
  "That folder is not there, and openGym could not make it. Make it on the server first.": "Kansiota ei ole, eikä openGym pystynyt luomaan sitä. Luo se ensin palvelimelle.",
  "The server says this account may not write there.": "Palvelimen mukaan tällä tilillä ei ole kirjoitusoikeutta sinne.",
  "The server is out of space for this account.": "Palvelimella ei ole enää tilaa tälle tilille.",
  "Could not reach the server. In a browser it also has to allow this site (CORS), see the guide.": "Palvelimeen ei saatu yhteyttä. Selaimessa sen on myös sallittava tämä sivusto (CORS), katso ohje.",
  "Type the password again: this device does not have it.": "Kirjoita salasana uudelleen: tällä laitteella ei ole sitä.",
  "That file is not an openGym backup.": "Tämä tiedosto ei ole openGym-varmuuskopio.",
  "Nothing to back up yet: log a workout first.": "Ei vielä varmuuskopioitavaa: kirjaa ensin treeni.",
  "The server answered with an error.": "Palvelin vastasi virheellä.",
  "Paste the address of the folder on your WebDAV server.": "Liitä WebDAV-palvelimesi kansion osoite.",
  "That does not look like an address.": "Tuo ei näytä osoitteelta.",
  "Leave the name and password out of the address, they have their own fields.": "Jätä nimi ja salasana pois osoitteesta, niillä on omat kenttänsä.",
  "Strava was not given access. Nothing was connected.": "Stravalle ei annettu käyttöoikeutta. Mitään ei yhdistetty.",
  "Strava has to be allowed to upload activities. Connect again and leave that box ticked.": "Stravalla on oltava lupa ladata suorituksia. Yhdistä uudelleen ja jätä kyseinen ruutu valituksi.",
  "That sign-in took too long or came from somewhere else. Start again from here.": "Kirjautuminen kesti liian kauan tai tuli muualta. Aloita tästä uudelleen.",
  "Sign in to your server first, then connect Strava.": "Kirjaudu ensin palvelimellesi ja yhdistä sitten Strava.",
  "Strava is off on this server.": "Strava on pois päältä tällä palvelimella.",
  "Strava could not be connected. Try again.": "Stravaa ei voitu yhdistää. Yritä uudelleen.",
  "Keeps the newest {0} backup, one per day.": "Säilyttää {0} uusimman varmuuskopion, yhden päivässä.",
  "Keeps the newest {0} backups, one per day.": "Säilyttää {0} uusinta varmuuskopiota, yhden päivässä.",
  "Steady double progression": "Tasainen tuplaprogressio",
  "Undulating days": "Vaihtelevat päivät",
  "Shorter rests": "Lyhyemmät tauot",
  "Work up a rep range one rep at a time. Every set has to hit the target before it moves, and at the top of the range the weight goes up.": "Etene toistoalueen läpi toisto kerrallaan. Jokaisen sarjan on saavutettava tavoite ennen nousua, ja alueen ylärajalla paino nousee.",
  "Each session rotates: a medium day at your reps, a heavy day with fewer, a light day with more. The weights come from your estimated max, so they climb as you get stronger.": "Jokainen treenikerta kiertää: keskiraskas päivä tavoitetoistoillasi, raskas päivä vähemmillä ja kevyt päivä useammilla. Painot lasketaan arvioidusta maksimistasi, joten ne nousevat vahvistuessasi.",
  "Same weight, a bit less rest each time every set is clean. At your shortest rest the weight goes up and the rest starts over.": "Sama paino, hieman lyhyempi tauko joka kerta, kun kaikki sarjat ovat puhtaita. Lyhimmän tauon kohdalla paino nousee ja tauko alkaa alusta.",
  "Every set hit {0}. Same weight, {1} reps this time.": "Jokainen sarja saavutti tavoitteen {0}. Sama paino, tällä kertaa {1} toistoa.",
  "Not every set reached {0} yet. Same weight and target again ({1} of {2} to go).": "Kaikki sarjat eivät vielä saavuttaneet tavoitetta {0}. Sama paino ja tavoite uudelleen ({1}/{2} jäljellä).",
  "Every set clean. Same weight with {0}s less rest: {1}s.": "Kaikki sarjat puhtaita. Sama paino, {0} s lyhyempi tauko: {1} s.",
  "Clean at your shortest rest. {0} {1} less help, rest back to {2}s.": "Puhdasta lyhimmällä tauolla. {0} {1} vähemmän apua, tauko takaisin: {2} s.",
  "Clean at your shortest rest. {0} {1} more, rest back to {2}s.": "Puhdasta lyhimmällä tauolla. {0} {1} lisää, tauko takaisin: {2} s.",
  "Stuck for {0} sessions. Same weight with more rest: {1}s.": "Jumiutunut {0} treenikerran ajaksi. Sama paino pidemmällä tauolla: {1} s.",
  "Missed reps last time. Same weight and rest again ({0} of {1} to go).": "Toistoja jäi viimeksi vajaaksi. Sama paino ja tauko uudelleen ({0}/{1} jäljellä).",
  "Heavy day: {0} reps at {1} {2}, from your estimated max of {3} {2}.": "Raskas päivä: {0} toistoa painolla {1} {2}, arvioidusta maksimistasi {3} {2}.",
  "Light day: {0} reps at {1} {2}, from your estimated max of {3} {2}.": "Kevyt päivä: {0} toistoa painolla {1} {2}, arvioidusta maksimistasi {3} {2}.",
  "Medium day: {0} reps at {1} {2}, from your estimated max of {3} {2}.": "Keskiraskas päivä: {0} toistoa painolla {1} {2}, arvioidusta maksimistasi {3} {2}.",
  "Rest down to (s)": "Tauko alimmillaan (s)",
