  "This version of openGym comes without the Garmin link, since Garmin’s part of it isn’t open source. The App Store, Google Play and GitHub versions have it.": "Tässä openGym-versiossa ei ole Garmin-yhteyttä, koska Garminin osuus ei ole avointa lähdekoodia. App Store-, Google Play- ja GitHub-versioissa se on mukana.",
  "Garmin Connect isn’t on this phone. Install it, pair your watch there, then come back here.": "Garmin Connectia ei ole tässä puhelimessa. Asenna se, yhdistä kellosi siellä ja palaa sitten tänne.",
  "Garmin Connect needs an update before openGym can talk to your watch.": "Garmin Connect täytyy päivittää, ennen kuin openGym voi keskustella kellosi kanssa.",
  "Couldn’t reach Garmin Connect. Try again in a moment.": "Garmin Connectiin ei saatu yhteyttä. Yritä hetken kuluttua uudelleen.",
  "Pick your Garmin in Garmin Connect and your workouts show up on your wrist.": "Valitse Garmin-kellosi Garmin Connectissa, niin treenisi näkyvät ranteessasi.",
  "Your Garmin isn’t in reach right now. Bring it close with Bluetooth on, and this page catches up by itself.": "Garminisi ei ole juuri nyt kantoalueella. Tuo se lähelle Bluetooth päällä, niin tämä sivu päivittyy itsestään.",
  "Garmin Connect doesn’t know a watch yet. Pair yours there first.": "Garmin Connect ei tunne vielä yhtään kelloa. Yhdistä omasi siellä ensin.",
  "openGym is on your Garmin. Sets you log on the wrist land here.": "openGym on Garminissasi. Ranteessa kirjaamasi sarjat tulevat tänne.",
  "openGym is on your Garmin. It catches up as soon as the watch is in reach.": "openGym on Garminissasi. Se päivittyy heti, kun kello on kantoalueella.",
  "Your Garmin is here, openGym isn’t on it yet. Get it, then open it once on the watch.": "Garminisi on täällä, mutta openGym ei ole vielä siinä. Hanki se ja avaa se kerran kellossa.",
