  "For the Daily form card in Stats and your check-in. Read on this phone only, never sent anywhere.": "Tilastojen Päivän kunto -korttia ja tilannekatsaustasi varten. Luetaan vain tässä puhelimessa, ei lähetetä minnekään.",
  "Four taps on sleep, energy, soreness and stress. On a rough day openGym offers to go lighter, and after a few weeks you see what your good days have in common.": "Neljä napautusta unesta, energiasta, lihaskivusta ja stressistä. Rankkana päivänä openGym ehdottaa kevyempää treeniä, ja muutaman viikon kuluttua näet, mikä hyviä päiviäsi yhdistää.",
