  "More than last month. Momentum looks good on you.": "Enemmän kuin viime kuussa. Hyvä vauhti pukee sinua.",
  "New moves, new muscles asking questions. Curiosity pays.": "Uusia liikkeitä, uusia lihaksia ihmettelemässä. Uteliaisuus kannattaa.",
