  "When your numbers dip two weeks running (and your check-ins say tired, if you log them), Home asks.": "Kun tuloksesi laskevat kaksi viikkoa peräkkäin (ja tilannekatsauksissa näkyy väsymys, jos kirjaat niitä), Koti kysyy.",
