  "{0}% fewer sets, same weights. Recharge.": "{0} % vähemmän sarjoja, samat painot. Lataa akkuja.",
  "{1} are still recovering, so they sit this one out.": "{1} palautuvat vielä, joten ne jättävät tämän kerran väliin.",
  "{1} is still recovering, so it sits this one out.": "{1} palautuu vielä, joten se jättää tämän kerran väliin.",
  "And it stays that way: openGym Offline has no internet permission, so Android blocks anything it might try.": "Ja sellaisena se pysyy: openGym Offline -sovelluksella ei ole internet-oikeutta, joten Android estää kaiken, mitä se yrittäisikin.",
  "Any of the sounds on your phone.": "Mikä tahansa puhelimesi äänistä.",
  "Back it up now and then in Settings, Data & backup. A file on your phone is the only copy there is.": "Varmuuskopioi silloin tällöin kohdassa Asetukset, Tiedot ja varmuuskopiointi. Puhelimessasi oleva tiedosto on ainoa kopio.",
  "Closing the app resets the count; the log never leaves the phone.": "Sovelluksen sulkeminen nollaa laskurin; loki ei koskaan poistu puhelimesta.",
  "Counting since {0}, when the app started. Closing the app resets it; the log never leaves the phone.": "Laskettu ajankohdasta {0}, jolloin sovellus käynnistettiin. Sulkeminen nollaa sen; loki ei koskaan poistu puhelimesta.",
  "Each reminder can sound different, so you know which one it is before you look.": "Jokainen muistutus voi kuulostaa erilaiselta, joten tiedät jo katsomatta, mistä on kyse.",
  "Everything this app asked the internet for, newest first. The address only, never what was in it.": "Kaikki, mitä tämä sovellus on internetistä pyytänyt, uusin ensin. Vain osoite, ei koskaan sisältöä.",
  "For reading mid-set without your glasses.": "Lukemiseen kesken sarjan ilman silmälaseja.",
  "Larger": "Suurempi",
  "Last at {0}": "Viimeksi {0}",
  "Latest": "Viimeisin",
  "Less: no sliding, bouncing or snow. Things just appear.": "Vähemmän: ei liukumista, pomppimista eikä lumisadetta. Asiat vain ilmestyvät.",
  "Like the phone": "Kuten puhelimessa",
  "Mostly your own server, {0}, when there was something to sync.": "Enimmäkseen oma palvelimesi, {0}, kun synkronoitavaa oli.",
  "Motion": "Liike",
  "Network log": "Verkkoloki",
  "No map search in openGym Offline. Stand in your gym, tap Current location, done.": "openGym Offline ei sisällä karttahakua. Seiso salillasi, napauta Nykyinen sijainti, valmista.",
  "Not a single byte left this phone. Your training is nobody’s business but yours.": "Yksikään tavu ei lähtenyt tästä puhelimesta. Treenisi ei kuulu kenellekään muulle.",
  "Nothing yet. Your server hears from this phone when there is something to sync.": "Ei vielä mitään. Palvelimesi kuulee tästä puhelimesta, kun synkronoitavaa on.",
  "Phone default": "Puhelimen oletus",
  "Phone sound": "Puhelimen ääni",
  "Pick a phone sound…": "Valitse puhelimen ääni…",
  "Showing the last {0}. The count above has them all.": "Näytetään viimeisimmät {0}. Yllä oleva laskuri sisältää ne kaikki.",
  "Shows up, keeps quiet.": "Näkyy, mutta pysyy hiljaa.",
  "Tap one to hear it. It rings even with the app closed.": "Kuuntele napauttamalla. Se soi myös sovelluksen ollessa suljettuna.",
  "Text size": "Tekstin koko",
  "This is openGym Offline: Android doesn’t even let it on the internet. Want sync? The normal openGym app can do that, next to this one.": "Tämä on openGym Offline: Android ei edes päästä sitä internetiin. Haluatko synkronoinnin? Tavallinen openGym-sovellus osaa sen, tämän rinnalla.",
  "Weigh-ins, measurements and progress photos.": "Punnitukset, mitat ja edistymiskuvat.",
