  "When you walk into your gym.": "Kun astut sisään salillesi.",
  "Who": "Kuka",
  "Who this app talked to since you opened it.": "Kenen kanssa tämä sovellus on jutellut avaamisesta lähtien",
  "Workout days and the nudge when one slips by.": "Treenipäivät ja pieni tönäisy, kun yksi meinaa lipsua.",
  "Workout reminders": "Treenimuistutukset",
  "openGym Offline has no internet permission. Your training stays on this phone, full stop.": "openGym Offline -sovelluksella ei ole internet-oikeutta. Treenisi pysyvät tässä puhelimessa, piste.",
  "openGym Offline never checks for updates, it can’t. New versions come from wherever you got this one.": "openGym Offline ei koskaan tarkista päivityksiä, eikä pystykään siihen. Uudet versiot tulevat sieltä, mistä hankit tämänkin.",
  "openGym Offline, no internet permission": "openGym Offline, ei internet-oikeutta",
