  "This backup belongs to another account": "Tämä varmuuskopio kuuluu toiselle tilille",
  "Someone else set it up on this device, so nothing of yours goes to their folder. Disconnect it to set up your own.": "Joku muu on ottanut sen käyttöön tällä laitteella, joten mikään sinun tietosi ei mene hänen kansioonsa. Katkaise yhteys, jos haluat ottaa oman käyttöön.",
  "Routine from a past workout": "Ohjelma aiemmasta treenistä",
  "From a past workout": "Aiemmasta treenistä",
  "Pick one you did, imported ones too. Its exercises and sets become a routine you can tweak.": "Valitse jokin tekemäsi treeni, myös tuodut kelpaavat. Sen liikkeistä ja sarjoista tehdään ohjelma, jota voit muokata.",
  "That workout has no exercises to copy.": "Siinä treenissä ei ole kopioitavia liikkeitä.",
  "Saved as a routine. Your workout stays as it was.": "Tallennettu ohjelmana. Treenisi säilyy ennallaan.",
  "Nothing logged yet. Train once, or import your history, and it shows up here.": "Ei vielä kirjauksia. Treenaa kerran tai tuo historiasi, niin ne näkyvät täällä.",
  "Smallest": "Pienin",
  "Largest": "Suurin",
  "Follows your phone’s text size, now {0}.": "Noudattaa puhelimen tekstikokoa, nyt {0}.",
