  "Back in the workout. Pick up where you left off.": "Takaisin treenissä. Jatka siitä, mihin jäit.",
  "Ended by itself when you left the gym": "Lopetettu itsestään, kun lähdit salilta",
  "Ended by itself after a quiet spell": "Lopetettu itsestään hiljaisen hetken jälkeen",
  "Saved as ending at {0}, after your last set and its rest.": "Tallennettu päättymään klo {0}, viimeisen sarjan ja sen tauon jälkeen.",
  "Reopen workout": "Avaa treeni uudelleen",
  "Still training?": "Vieläkö treenaat?",
  "No set for {0} minutes. If you’re done, I’ll wrap it up in {1} minutes, ending at your last set.": "Ei sarjaa {0} minuuttiin. Jos olet valmis, päätän treenin {1} minuutin päästä viimeiseen sarjaasi.",
  "Looks like you left the gym": "Näyttää siltä, että lähdit salilta",
  "Finish the workout now? Otherwise it ends by itself in {0} minutes.": "Lopetetaanko treeni nyt? Muuten se päättyy itsestään {0} minuutin kuluttua.",
  "Keep going": "Jatka",
  "Finish now": "Lopeta nyt",
  "Finish the workout now? Otherwise it ends by itself at {0}.": "Lopetetaanko treeni nyt? Muuten se päättyy itsestään klo {0}.",
  "Nothing logged for a while. If you’re done, it ends by itself at {0}, saved at your last set.": "Mitään ei ole kirjattu hetkeen. Jos olet valmis, treeni päättyy itsestään klo {0}, ja sen lopuksi tallentuu viimeinen sarjasi.",
  "Forgotten workouts": "Unohtuneet treenit",
  "If nobody answers, it finishes by itself and never throws anything away. The end is your last set plus its rest, so the time stays honest. Reopen it from History for a day. Your watch asks too.": "Jos kukaan ei vastaa, treeni päättyy itsestään eikä mitään heitetä pois. Päättymisajaksi tulee viimeinen sarja sekä sen tauko, joten kesto pysyy rehellisenä. Voit avata sen uudelleen historiasta vuorokauden ajan. Kellokin kysyy.",
  "Never asks and never ends one by itself.": "Ei koskaan kysy eikä koskaan lopeta treeniä itsestään.",
  "The default. Long enough for a chat at the water fountain.": "Oletus. Riittää pieneen juttutuokioon vesiautomaatilla.",
  "Asks the moment your phone walks out of your gym, then wraps up.": "Kysyy heti, kun puhelimesi kävelee ulos salilta, ja päättää sitten treenin.",
  "Needs the gym reminder: {0}.": "Vaatii salimuistutuksen: {0}.",
  "Save to Photos": "Tallenna Kuviin",
