  "Could not save the picture.": "Kuvaa ei voitu tallentaa.",
  "openGym may not add pictures to Photos. You can allow it in the phone settings.": "openGym ei saa lisätä kuvia Kuviin. Voit sallia sen puhelimen asetuksista.",
  "A preset sets every surface. Then change whatever you like.": "Esiasetus määrittää kaikki näkymät. Sen jälkeen voit muuttaa mitä haluat.",
