  "Minimal": "Pelkistetty",
  "Needs iOS 17 or later. No animations on the Lock Screen, so the exercise picture is a still. Buttons work without unlocking, Finish opens the app.": "Vaatii iOS 17:n tai uudemman. Lukitusnäytöllä ei ole animaatioita, joten liikkeen kuva on pysäytyskuva. Painikkeet toimivat ilman lukituksen avaamista, Lopeta avaa sovelluksen.",
  "No buttons. A tap on it opens openGym.": "Ei painikkeita. Napauttamalla avaat openGymin.",
  "No room on the Lock Screen. Apple keeps Live Activities to about 160 points tall.": "Lukitusnäytöllä ei ole tilaa. Apple rajaa Live-toimintojen korkeuden noin 160 pisteeseen.",
  "No tiles yet.": "Ei vielä ruutuja.",
  "Nothing here yet, so the workout screen stays as it is. Add a tile or pick a preset.": "Täällä ei ole vielä mitään, joten treeninäyttö pysyy ennallaan. Lisää ruutu tai valitse esiasetus.",
  "Opens openGym, since saving asks what to keep.": "Avaa openGymin, sillä tallennettaessa kysytään, mitä säilytetään.",
  "Six tiles fit in a notification before it starts mumbling.": "Ilmoitukseen mahtuu kuusi ruutua, ennen kuin se alkaa mutista.",
  "Size of {0}": "Kohteen {0} koko",
  "The Dynamic Island holds four tiles. It is an island, not a continent.": "Dynamic Islandiin mahtuu neljä ruutua. Se on saari, ei manner.",
  "The pill": "Pilleri",
  "The pill has two spots, one each side of the camera.": "Pillerissä on kaksi paikkaa, yksi kameran kummallakin puolella.",
  "The pill shows two tiles beside the camera. Long-press it for the rest.": "Pilleri näyttää kaksi ruutua kameran vieressä. Näet loput painamalla pitkään.",
  "The widget fits three lines under the set.": "Widgetiin mahtuu kolme riviä sarjan alle.",
  "Three buttons fit in the Dynamic Island.": "Dynamic Islandiin mahtuu kolme painiketta.",
  "Tiles": "Ruudut",
  "Tiles become lines of text, so Android 16 can keep it a Live Update by the clock. While a rest runs, the notification shows its rest buttons.": "Ruuduista tulee tekstirivejä, jotta Android 16 voi pitää sen Live-päivityksenä kellon vieressä. Tauon aikana ilmoituksessa näkyvät taukopainikkeet.",
  "Up to three lines under the set. The widget keeps its own − and + buttons.": "Enintään kolme riviä sarjan alle. Widget säilyttää omat −- ja +-painikkeensa.",
  "Where it shows": "Missä se näkyy",
