  "Record hints": "Ennätysvihjeet",
  "Resting": "Tauolla",
  "Short words beside the set. Heart rate and calories come from the main page.": "Lyhyet sanat sarjan vieressä. Syke ja kalorit tulevat pääsivulta.",
  "Show": "Näytä",
  "Show a strip in the workout": "Näytä palkki treenissä",
  "Strength set": "Voimasarja",
  "Superset with {0}": "Supersarja: {0}",
  "The Lock Screen and the notification come with the phone apps. This is how they look there.": "Lukitusnäyttö ja ilmoitus tulevat puhelinsovellusten mukana. Tältä ne näyttävät siellä.",
  "The set, the clock and the buttons, with up to two extras.": "Sarja, kello ja painikkeet sekä enintään kaksi lisätietoa.",
  "Timed hold": "Ajastettu pito",
  "Use the defaults for {0}": "Käytä oletuksia ({0})",
  "Weight and reps": "Paino ja toistot",
  "What comes after this exercise, plus heart rate and calories when they’re on. The rest is on the screen already.": "Mikä tulee tämän liikkeen jälkeen sekä syke ja kalorit, kun ne ovat päällä. Loput näkyvät jo näytöllä.",
  "What’s next": "Seuraavaksi",
  "Your workout": "Treenisi",
  "“2 more reps for a record”, in the detailed look.": "”Vielä 2 toistoa ennätykseen”, yksityiskohtaisessa näkymässä.",
  "− and + on the set, so you can fix it without unlocking.": "− ja + sarjan kohdalla, jotta voit korjata sitä avaamatta lukitusta.",
  "Animations standing still? iOS can pause them: in Settings, under Accessibility › Motion, turn on Auto-Play Animated Images.": "Eivätkö animaatiot liiku? iOS voi pysäyttää ne: laita Asetuksissa kohdassa Käyttöapu › Liike päälle Toista animoidut kuvat automaattisesti.",
  "Level {0} next time": "Taso {0} ensi kerralla",
  "Still connecting to your Apple Watch. Give it a moment, then open this page again.": "Yhdistetään edelleen Apple Watchiin. Odota hetki ja avaa tämä sivu sitten uudelleen.",
  "No Apple Watch is paired with this iPhone. Pair one in the Watch app, then install openGym on it there.": "Tähän iPhoneen ei ole yhdistetty Apple Watchia. Yhdistä kello Watch-sovelluksessa ja asenna openGym siihen sieltä.",
  "openGym is not on your Apple Watch yet. Open the Watch app on this iPhone, find openGym under Available Apps and tap Install.": "openGym ei ole vielä Apple Watchissasi. Avaa tämän iPhonen Watch-sovellus, etsi openGym kohdasta Saatavilla olevat apit ja napauta Asenna.",
  "Connected right now.": "Yhdistetty juuri nyt.",
  "The watch app is closed or out of reach right now. Sets you log on the watch are kept there and arrive when the two are in touch again.": "Kellosovellus on suljettu tai tavoittamattomissa juuri nyt. Kellossa kirjaamasi sarjat pysyvät siellä tallessa ja siirtyvät, kun laitteet ovat taas yhteydessä.",
  "No Wear OS watch is connected to this phone. Pair one in its own app (Galaxy Wearable, Pixel Watch), then come back here.": "Tähän puhelimeen ei ole yhdistetty Wear OS -kelloa. Yhdistä kello sen omassa sovelluksessa (Galaxy Wearable, Pixel Watch) ja palaa sitten tänne.",
  "Your watch is here, openGym isn’t on it yet. On the watch, open the Play Store and install openGym from “Apps on your phone”.": "Kellosi on tässä, mutta openGym ei ole vielä siinä. Avaa kellossa Play Kauppa ja asenna openGym kohdasta ”Puhelimesi sovellukset”.",
  "Your watch is here, openGym isn’t on it yet. This phone runs the openGym APK, so the watch needs the Wear OS APK of the same release. One from Google Play won’t pair with it.": "Kellosi on tässä, mutta openGym ei ole vielä siinä. Tässä puhelimessa on openGym-APK, joten kello tarvitsee saman julkaisun Wear OS -APK:n. Google Playn versio ei toimi parina sen kanssa.",
  "openGym is on your watch and in reach. Sets you log on the wrist land here.": "openGym on kellossasi ja yhteyden päässä. Ranteessa kirjaamasi sarjat päätyvät tänne.",
  "openGym is on your watch, but the watch is out of reach right now. Sets you log on it wait there and land here once it is back.": "openGym on kellossasi, mutta kello on nyt tavoittamattomissa. Siellä kirjaamasi sarjat odottavat kellossa ja siirtyvät tänne, kun yhteys palaa.",
  "Get openGym for Wear OS": "Hanki openGym Wear OS:lle",
  "Your watches": "Kellosi",
  "Start a workout on the phone and it shows up on your watch. One tap opens it.": "Aloita treeni puhelimessa, niin se ilmestyy kelloosi. Yksi napautus avaa sen.",
  "Off on this phone. Your choices below still apply to your other devices and the Home Screen widget.": "Pois päältä tässä puhelimessa. Alla olevat valintasi koskevat silti muita laitteitasi ja kotinäytön widgetiä.",
  "The rest timer keeps its own notification.": "Taukoajastin pitää oman ilmoituksensa.",
  "This needs iOS 17 or later. This iPhone is on an older version.": "Tämä vaatii iOS 17:n tai uudemman. Tässä iPhonessa on vanhempi versio.",
  "Notifications are off for openGym, so Android has nowhere to show this.": "openGymin ilmoitukset ovat pois päältä, joten Androidilla ei ole paikkaa näyttää tätä.",
  "Swipe home to see it in the Dynamic Island, or lock your phone for the Lock Screen.": "Pyyhkäise kotinäyttöön nähdäksesi sen Dynamic Islandissa tai lukitse puhelin nähdäksesi lukitusnäytön.",
  "Your phone did not show it. “Not showing up?” at the bottom has the usual reasons.": "Puhelimesi ei näyttänyt sitä. Alareunan ”Eikö näy?” kertoo tavallisimmat syyt.",
  "While you use other apps": "Kun käytät muita sovelluksia",
  "When you touch and hold it": "Kun pidät sitä painettuna",
  "Adds a progress bar and up to four extras.": "Lisää edistymispalkin ja enintään neljä lisätietoa.",
  "During a set": "Sarjan aikana",
  "During a rest": "Tauon aikana",
  "The whole workout": "Koko treeni",
  "Less weight and More weight in the notification. They take both free places, so the other buttons step aside.": "Vähemmän painoa ja Enemmän painoa ilmoituksessa. Ne vievät molemmat vapaat paikat, joten muut painikkeet väistyvät.",
  "A running clock in the corner while a set is up.": "Käyvä kello kulmassa sarjan ollessa käynnissä.",
  "“2 more reps for a record”, on the Home Screen widget.": "”Vielä 2 toistoa ennätykseen”, kotinäytön widgetissä.",
  "Hidden while the picture or the − and + buttons are showing.": "Piilotettu, kun kuva tai painikkeet − ja + ovat näkyvissä.",
  "No room right now.": "Ei tilaa juuri nyt.",
  "Not showing up?": "Eikö näy?",
  "It shows up when a workout starts and leaves when you finish.": "Se ilmestyy, kun treeni alkaa, ja katoaa, kun lopetat.",
  "Allow Live Activities": "Salli Live-toiminnot",
  "iPhone Settings, openGym, Live Activities.": "iPhonen Asetukset, openGym, Live-toiminnot.",
  "Allow it on a locked phone": "Salli lukitussa puhelimessa",
  "iPhone Settings, the passcode page, then Live Activities under Allow Access When Locked.": "iPhonen Asetukset, pääsykoodisivu ja sitten Live-toiminnot kohdassa Salli käyttö lukittuna.",
  "Leave the app": "Poistu sovelluksesta",
  "The Dynamic Island only shows it while openGym is not on screen.": "Dynamic Island näyttää sen vain, kun openGym ei ole näytöllä.",
  "Gone after a swipe or a very long session": "Katoaa pyyhkäisyllä tai todella pitkän treenikerran jälkeen",
  "iOS ends it after 8 hours, and a swipe removes it. It comes back with your next set.": "iOS lopettaa sen 8 tunnin kuluttua, ja pyyhkäisy poistaa sen. Se palaa seuraavan sarjan myötä.",
  "Allow notifications": "Salli ilmoitukset",
  "Android Settings, Apps, openGym, Notifications.": "Androidin asetukset, Sovellukset, openGym, Ilmoitukset.",
  "Own setup for {0}": "Omat asetukset: {0}",
  "Follows the main page. Switch this on to pick the details and buttons for this type yourself.": "Seuraa pääsivua. Laita tämä päälle, niin voit valita tämän tyypin tiedot ja painikkeet itse.",
